classes:
className={`relative rounded-lg px-4 py-2 text-sm font-medium flex items-center gap-2 transition-colors ${isActive
                ? "text-heading"
                : "text-muted hover:text-heading hover:bg-gray-100 dark:hover:bg-white/[0.06]"
            }`}

className={`h-2 w-2 rounded-full transition-colors ${index === currentIndex
                    ? "bg-gray-800 dark:bg-white"
                    : "bg-gray-500 dark:bg-white/60 hover:bg-gray-700 dark:hover:bg-white/80"
                    }`}

className={`rounded-xl border border-gray-300 dark:border-white/10 object-cover shadow-lg ${activeDevice === "iphone"
											? "aspect-[9/16] w-[260px]"
											: "aspect-[4/3] w-[360px]"
											}`}

className={`block py-2 transition-all duration-200 border-l-2 -ml-[2px] ${level === 3 ? "pl-7" : "pl-5"
                                } ${activeId === id
                                    ? "border-gray-900 dark:border-white text-heading font-semibold"
                                    : "border-transparent text-gray-600 dark:text-gray-400 hover:text-heading hover:border-gray-400 dark:hover:border-gray-600"
                                }`}

className={`relative rounded-lg p-2 transition-colors ${isActive
								? "text-heading"
								: "text-muted hover:text-body hover:bg-gray-200 dark:hover:bg-white/10"
								}`}
